    // nested nodes) each entry's end is kept too.
    starts: std.ArrayListUnmanaged(u32) = .empty,
    ends: std.ArrayListUnmanaged(u32) = .empty,
    nodes: NodeStore = .{},
    sides: std.ArrayListUnmanaged(SideEntry) = .empty,
    reduction: Reduction = .{},
